import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.rZZZX73S.js";var c=JSON.parse(`{"title":"AppleSkinPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/apple-skin-pumpkin/docs/index.md"},"headers":[],"relativePath":"packages/apple-skin-pumpkin/docs/index.md","filePath":"packages/apple-skin-pumpkin/docs/index.md","lastUpdated":1791428389000}`),l={name:`packages/apple-skin-pumpkin/docs/index.md`},u={id:`appleskinpumpkin`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/apple-skin-pumpkin-v0.0.7`,"aria-label":`Release v0.0.7`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/apple-skin-pumpkin/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`AppleSkinPumpkin `),n(`a`,{class:`header-anchor`,href:`#appleskinpumpkin`,"aria-label":`Permalink to “AppleSkinPumpkin”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.0.7`})])]),c[2]||=r(`<p>AppleSkinPumpkin sends Java Edition clients the current saturation, exhaustion, and food-healing state that AppleSkin needs for its HUD. Install the AppleSkin client mod separately; this server plugin supplies the live values.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to “Install”">​</a></h2><p>Place <code>apple-skin-pumpkin.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory and restart the server. The first load asks for the plugin&#39;s permissions in the server console. A hot reload cannot show that prompt.</p><h2 id="what-clients-receive" tabindex="-1">What clients receive <a class="header-anchor" href="#what-clients-receive" aria-label="Permalink to “What clients receive”">​</a></h2><p>The plugin checks online players once per tick and sends an update only when one of the tracked values changes. Vanilla does not regularly send saturation and exhaustion updates in the form the AppleSkin HUD needs, so the plugin provides those updates directly. Bedrock players are skipped; AppleSkin is a Java Edition mod.</p><h2 id="diagnose-updates" tabindex="-1">Diagnose updates <a class="header-anchor" href="#diagnose-updates" aria-label="Permalink to “Diagnose updates”">​</a></h2><p>Set <code>log.level</code> to <code>debug</code> in the Pumpkin server configuration to see the values sent, plus join, leave, and skip events. Ticks with no changes stay quiet. The plugin has no separate configuration file or player commands.</p>`,7)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};